import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import javax.sql.DataSource;
import org.joget.apps.app.service.AppUtil;
import org.joget.commons.util.LogUtil;
import org.joget.commons.util.UuidGenerator;


DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
Connection con = null;
PreparedStatement stmt = null;
ResultSet rs = null;

int count = 0;

// Logging input value and UUID
LogUtil.info("check-formation",value);

try {
    con = ds.getConnection();
    LogUtil.info("check-formation", "Database connection established.");

    if (!con.isClosed()) {
        // Adding delimiters to avoid partial matches
        String selectSql = "SELECT COUNT(*) FROM app_fd_etablissement WHERE CONCAT(';', c_formation, ';') LIKE ?;";
        LogUtil.info("check-formation", "Prepared SQL: " + selectSql);

        stmt = con.prepareStatement(selectSql);

        String searchPattern = "%;" + value + ";%";
        LogUtil.info("check-formation", "Using search pattern: " + searchPattern);

        stmt.setString(1, searchPattern);

        rs = stmt.executeQuery();
        if (rs.next()) {
            count = rs.getInt(1);
            LogUtil.info("check-formation", "Count of matched formations: " + count);
        }
    }
} catch (SQLException e) {
    LogUtil.error("check-formation", e, "Error during SQL execution: " + e.getMessage());
} finally {
    try {
        if (rs != null) {
            rs.close();
            LogUtil.info("check-formation", "ResultSet closed.");
        }
        if (stmt != null) {
            stmt.close();
            LogUtil.info("check-formation", "PreparedStatement closed.");
        }
        if (con != null) {
            con.close();
            LogUtil.info("check-formation", "Connection closed.");
        }
    } catch (Exception ex) {
        LogUtil.warn("check-formation", "Error closing resources: " + ex.getMessage());
    }
}

if (count == 0) {
    LogUtil.info("check-formation", "Returning TRUE for value: " + value);
    return "<span>True</span>";
} else {
    LogUtil.info("check-formation", "Returning FALSE for value: " + value);
    return "<span>False</span>";
}
